def transform(grid):
    h, w = len(grid), len(grid[0])
    anchors = {r: row[0] for r, row in enumerate(grid) if row[0] != 0}
    # With unknown pattern period, choose the shortest period that agrees with
    # all observed rows; initialize unobserved phases by nearest anchor.
    period = next((p for p in range(1, h + 1)
                   if all(not any((r - s) % p == 0 and c != v
                                  for s, c in anchors.items())
                          for r, v in anchors.items())), h)
    phases = {}
    for r, v in anchors.items():
        phases[r % period] = v
    known = sorted(phases)
    seq = []
    for i in range(period):
        if i in phases:
            seq.append(phases[i])
        else:
            # Extend pattern through missing phase using cyclic nearest known phase.
            seq.append(phases[min(known, key=lambda j: (i-j) % period)])
    return [[seq[r % period]] * w for r in range(h)]

def transform(grid):
    h, w = len(grid), len(grid[0])
    anchors = {r: row[0] for r, row in enumerate(grid) if row[0] != 0}
    period = next(p for p in range(1, h + 1)
                  if all(anchors[r] == anchors[s]
                         for r in anchors for s in anchors
                         if r % p == s % p))
    phases = {}
    for r, color in anchors.items():
        phases[r % period] = color
    # Fill unobserved phases with the nearest preceding known phase cyclically.
    known = set(phases)
    for phase in range(period):
        if phase not in phases:
            prior = min(known, key=lambda k: (phase - k) % period)
            phases[phase] = phases[prior]
    return [[phases[r % period]] * w for r in range(h)]
